import { FC } from "react";
import Link from "next/link";
import { graphqlRequestNoCache } from "../../lib/graphql-fetch";
import { GET_HOME_CATEGORIES } from "@/graphql/catelog/queries/HomeCategories";
import { GridTileImage } from "../theme/ui/grid/Tile";
import { NOT_IMAGE } from "@/utils/constants";

interface CategoryCarouselProps {
  options: {
    filters: Record<string, any>;
  };
}

const CategoryCarousel: FC<CategoryCarouselProps> = async ({
  options: _options,
}) => {
  try {
    const data = await graphqlRequestNoCache<any>(
      GET_HOME_CATEGORIES,
      { getCategoryTree: true }
    );

    const categories = data?.homeCategories || [];

    const topCategories = categories
      .filter((category: any) => category.id !== "1")
      .sort((a: any, b: any) => (a.position || 0) - (b.position || 0))
      .slice(0, 3);

    if (!topCategories.length) return null;

    return (
      <section className="pt-8 sm:pt-12 lg:pt-20">
        <div className="md:max-w-4.5xl mx-auto mb-10 w-auto text-center md:px-36">
          <h2 className="mb-2 text-xl md:text-4xl  font-semibold">
            Compra por categoría
          </h2>
          <p className="text-sm md:text-base font-normal text-black/60 dark:text-neutral-300">
            Descubre las últimas tendencias. Productos recién agregados: nuevas
            tendencias, tecnología y esenciales antes de que se agoten.
          </p>
        </div>
        <div className="w-full overflow-x-auto overflow-y-hidden">
          <ul className="m-0 grid grid-cols-1 gap-7 p-0 xss:grid-cols-2 sm:grid-cols-3">
            {topCategories.map((category: any) => (
              <li
                key={category.id}
                className="relative aspect-498/665 h-full w-full max-w-[498px] flex-none overflow-hidden rounded-[18px]"
              >
                <Link
                  className="relative h-full w-full"
                  href={`/search/${category.slug}`}
                  aria-label={`Comprar categoría ${category.name}`}
                >
                  <GridTileImage
                    fill
                    alt={`Imagen de la categoría ${category.name}`}
                    className={
                      "relative rounded-[18px] overflow-hidden object-cover transition duration-300 ease-in-out group-hover:scale-105"
                    }
                    label={{
                      title: category.name || "",
                      page: "category",
                      amount: "0",
                      currencyCode: "USD",
                    }}
                    src={category.logoUrl || category.bannerUrl || NOT_IMAGE}
                  />
                </Link>
              </li>
            ))}
          </ul>
        </div>
      </section>
    );
  } catch (error) {
    console.error("Error fetching categories:", error);
    return null;
  }
};

export default CategoryCarousel;

import { FC } from "react";
import { graphqlRequestNoCache } from "../../lib/graphql-fetch";
import { GET_PRODUCTS } from "@/graphql/catelog/queries/Product";
import { ThreeItemGrid } from "./ThreeItemGrid";
import Theme from "./ProductCarouselTheme";
import {
  buildStorefrontFilterInput,
  resolveSortToStorefrontFilters,
} from "@/utils/storefront-filters";
import { ProductsResponse } from "@/components/catalog/type";


interface ProductCarouselProps {
    options: {
        title?: string;
        filters: Record<string, any>;
    };
    itemCount?: number;
    sortOrder?: number;
}

const ProductCarousel: FC<ProductCarouselProps> = async ({ options, itemCount = 4, sortOrder }) => {
    const { filters, title } = options;
    try {
        const normalizedFilters = Array.isArray(filters)
            ? filters.reduce<Record<string, string>>((acc, item) => {
                if (item?.key) {
                    acc[item.key] = String(item.value ?? "");
                }
                return acc;
            }, {})
            : (filters || {});

        const { sort, limit, ...rest } = normalizedFilters as Record<string, any>;
        const parsedLimit = Number.parseInt(String(limit), 10);

        const input = buildStorefrontFilterInput({
            base: {
            page: 1,
            limit: Number.isFinite(parsedLimit) && parsedLimit > 0 ? parsedLimit : itemCount,
            ...resolveSortToStorefrontFilters(
              typeof sort === "string" ? sort : undefined
            ),
            ...rest,
          },
        });

        const data = await graphqlRequestNoCache<ProductsResponse>(
            GET_PRODUCTS,
            { input }
        );

        const products = (data?.products?.data || [])
          .slice(0, 8)
          .map((product) => ({
            id: product.id,
            sku: product.sku,
            name: product.name || product.sku,
            urlKey: product.urlKey || product.sku,
            baseImageUrl: product.baseImageUrl ?? undefined,
            images: Array.isArray(product.images) ? product.images : undefined,
            cacheBaseImage: Array.isArray(product.cacheBaseImage)
              ? product.cacheBaseImage
              : product.cacheBaseImage
                ? [product.cacheBaseImage]
                : undefined,
            price: product.price ?? "0",
            specialPrice: product.specialPrice ?? undefined,
            type: product.type || "simple",
          }));

        if (!products.length) {
            return null;
        }

        if (sortOrder === 2 && products.length >= 3) {
            return (
                <ThreeItemGrid
                    title={title || "Productos"}
                    description="Descubre las últimas tendencias. Productos recién agregados: nuevas tendencias, tecnología y esenciales antes de que se agoten."
                    products={products.slice(0, 3)}
                />
            );
        }

        return (

            <Theme
                title={title || "Productos"}
                description="Descubre las últimas tendencias. Productos recién agregados: nuevas tendencias, tecnología y esenciales antes de que se agoten."
                products={products}
            />
        );
    } catch (error) {
        console.error("Error fetching products for carousel:", {
            title,
            filters,
            error: error instanceof Error ? error.message : error
        });
        return null;
    }
};

export default ProductCarousel;

"use client";

import { SORT, SortOrderTypes } from "@/utils/constants";
import { createUrl } from "@/utils/helper";
import { Select, SelectItem } from "@heroui/select";
import { usePathname, useRouter, useSearchParams } from "next/navigation";
import { FC, useState, useEffect } from "react";
import {
  Drawer,
  DrawerContent,
  DrawerHeader,
  DrawerBody,
  Button,
  useDisclosure,
} from "@heroui/react";
import { SortIcon } from "@components/common/icons/SortIcon";



const SortOrder: FC<{
  sortOrders: SortOrderTypes[];
  title: string;
}> = ({ sortOrders, title }) => {
  const searchParams = useSearchParams();
  const pathname = usePathname();
  const router = useRouter();
  const sort = searchParams.get(SORT) || "name-asc";

  const { isOpen, onOpen, onOpenChange } = useDisclosure();
  const [tempSort, setTempSort] = useState(sort);

  useEffect(() => {
    setTempSort(sort);
  }, [sort]);

  const handleSortChange = (value: string) => {
    const newParams = new URLSearchParams(searchParams.toString());

    if (value) newParams.set(SORT, value);
    const newUrl = createUrl(pathname, newParams);

    router.replace(newUrl);
  };

  const applySort = () => {
    handleSortChange(tempSort);
    onOpenChange();
  };

  const clearFilters = () => {
    const q = searchParams.get("q");
    const newParams = new URLSearchParams();
    if (q) newParams.set("q", q);
    router.replace(createUrl(pathname, newParams));
    onOpenChange();
  };

  return (
    <>
      {/* Desktop View */}
      <section className="hidden md:flex w-64 items-center gap-x-2.5">
        <p
          id="sort-label"
          className="leading-0 text-nowrap min-[1300]:block hidden"
        >
          {title}
        </p>
        <Select
          defaultOpen={false}
          aria-label={title}
          aria-labelledby="sort-label"
          selectedKeys={[sort]}
          isMultiline={false}
          items={sortOrders}
          placeholder="Selecciona un orden"
          classNames={{
            value: "text-neutral-800 dark:text-neutral-200",
          }}
          renderValue={(items) => (
            <div className="flex items-center gap-1.5 overflow-x-auto pb-1.5 pt-1">
              {items.map((item) => (
                <p key={item.key} className="text-neutral-800 dark:text-neutral-200">{item.data?.title}</p>
              ))}
            </div>
          )}
          size="md"
          variant="flat"
          onSelectionChange={(e) => handleSortChange(e.currentKey as string)}
        >
          {(order) => (
            <SelectItem
              key={order.value}
              textValue={order.value}
              className="text-neutral-800 dark:text-neutral-200"
            >
              {order.title}
            </SelectItem>
          )}
        </Select>
      </section>

      {/* Mobile View Toggle */}
      <div className="md:hidden flex flex-wrap gap-3">
        <Button
          size="md"
          variant="flat"
          className="bg-neutral-100 dark:bg-neutral-800"
          onPress={onOpen}
        >
          <SortIcon />
          <span className="font-outfit text-base tracking-wide"> Ordenar</span>
        </Button>
      </div>

      {/* Mobile Bottom Sheet */}
      <Drawer
        isOpen={isOpen}
        placement="bottom"
        onOpenChange={onOpenChange}
        hideCloseButton
      >
        <DrawerContent className="rounded-t-[32px] dark:bg-neutral-900">
          {(_onClose) => (
            <>
              <DrawerHeader className="flex flex-col gap-1 pb-4 pt-2">
                <div className="mx-auto h-1 w-10 rounded-full bg-neutral-300 dark:bg-neutral-700" />
                <div className="flex items-center justify-between mt-2 px-2">
                  <h2 className="text-2xl font-bold tracking-tight">Ordenar</h2>
                  <div className="flex items-center gap-4">
                    {Array.from(searchParams.keys()).some((key) => key !== "q") && (
                      <button
                        onClick={clearFilters}
                        className="text-sm font-medium underline underline-offset-4 text-neutral-600 dark:text-neutral-400"
                      >
                        Limpiar filtros
                      </button>
                    )}
                    <Button
                      color="primary"
                      radius="full"
                      size="md"
                      className="px-6 font-semibold"
                      onPress={applySort}
                    >
                      Aplicar filtro
                    </Button>
                  </div>
                </div>
              </DrawerHeader>
              <DrawerBody className="px-6 pb-12 pt-2">
                <div className="flex flex-col gap-4">
                  <p className="text-lg font-semibold text-neutral-800 dark:text-neutral-200">
                    Ordenar por
                  </p>
                  <Select
                    aria-label="Opciones de orden"
                    selectedKeys={[tempSort]}
                    className="w-full"
                    variant="flat"
                    size="lg"
                    classNames={{
                      value: "text-neutral-800 dark:text-neutral-200",
                      trigger: "dark:bg-neutral-800",
                    }}
                    onSelectionChange={(e) =>
                      setTempSort(e.currentKey as string)
                    }
                  >
                    {sortOrders.map((order) => (
                      <SelectItem
                        key={order.value}
                        textValue={order.title}
                        className="text-neutral-800 dark:text-neutral-200"
                      >
                        {order.title}
                      </SelectItem>
                    ))}
                  </Select>
                </div>
              </DrawerBody>
            </>
          )}
        </DrawerContent>
      </Drawer>
    </>
  );
};

export default SortOrder;

"use client";

import { useEffect, useState, useRef } from "react";
import { fetchHandler } from "../fetch-handler";
import { GUEST_CART_ID, GUEST_CART_TOKEN, IS_GUEST } from "@/utils/constants";
import { encodeJWT, decodeJWT } from "@/utils/jwt-cookie";
import { setCookie, deleteCookie, getNativeCookie } from "../getCartToken";

let tokenCreated = false;
let tokenPromise: Promise<string | null> | null = null;

// ---------------------------
// Main Hook
// ---------------------------
export const useGuestCartToken = () => {
  const [token, setToken] = useState<string | null>(null);
  const [cartId, setCartId] = useState<number | null>(null);
  const [isReady, setIsReady] = useState(false);

  const isResettingRef = useRef(false);

  const createGuestToken = async (): Promise<string | null> => {
    if (tokenPromise) return tokenPromise;

    tokenPromise = (async () => {
      if (tokenCreated) {
        // Return existing raw token from cookie
        const cookieVal = getNativeCookie(GUEST_CART_TOKEN);
        if (cookieVal) {
          const isGuest = getNativeCookie(IS_GUEST) !== "false";
          const decoded = decodeJWT<{ sessionToken: string }>(cookieVal, isGuest);
          return decoded?.sessionToken ?? null;
        }
        return null;
      }
      tokenCreated = true;

      try {
        const res = await fetchHandler({
          url: "cart/createGuestToken",
          method: "POST",
          contentType: true,
        });

        const cart = res?.data?.createCartToken?.cartToken;
        if (!cart) {
          tokenCreated = false;
          return null;
        }

        const newToken = encodeJWT({
          sessionToken: cart.sessionToken,
          cartId: cart.id,
          isGuest: cart.isGuest,
        });
        const newCartId = Number(cart.id);

        setCookie(GUEST_CART_TOKEN, newToken);
        setCookie(GUEST_CART_ID, String(newCartId));
        setCookie(IS_GUEST, String(cart?.isGuest));

        // State and return should be the RAW token
        setToken(cart.sessionToken);
        setCartId(newCartId);
        return cart.sessionToken;
      } catch (e) {
        console.error("Error creating guest token:", e);
        tokenCreated = false;
        return null;
      } finally {
        tokenPromise = null;
      }
    })();

    return tokenPromise;
  };

  const resetGuestToken = async () => {
    if (isResettingRef.current) return;
    isResettingRef.current = true;

    tokenCreated = false;

    // delete old
    deleteCookie(GUEST_CART_TOKEN);
    deleteCookie(GUEST_CART_ID);

    await createGuestToken();

    isResettingRef.current = false;
  };

  useEffect(() => {
    const cookieToken = getNativeCookie(GUEST_CART_TOKEN);

    if (cookieToken) {
      const isGuest = getNativeCookie(IS_GUEST) !== "false";
      const decoded = decodeJWT<{
        sessionToken: string;
        cartId: number;
        isGuest: boolean;
      }>(cookieToken, isGuest);

      if (decoded) {
        setToken(decoded.sessionToken);
        setCartId(decoded.cartId);
      }
    }

    setIsReady(true);
  }, []);

  return {
    token,
    cartId,
    isReady,
    createGuestToken,
    resetGuestToken,
    deleteCookie,
  };
};

"use client";

import { useCustomToast } from "@/utils/hooks/useToast";
import { NOT_IMAGE, ORDER_ID } from "@/utils/constants";
import {
  CodCheckoutConfigResponse,
  CodOffer,
  CodOrderRequestBody,
} from "@/types/cod";
import { Price } from "@/components/theme/ui/Price";
import clsx from "clsx";
import { useEffect, useMemo, useRef, useState } from "react";
import { setCookie } from "@/utils/helper";
import { useRouter, useSearchParams } from "next/navigation";
import { NextImage } from "@/components/common/NextImage";

interface CodQuickCheckoutProps {
  productId: number;
}

type Step = 1 | 2 | 3;

const parseNumber = (value: unknown): number => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : 0;
};

const parseSelectionsFromSearch = (
  codes: string[],
  searchParams: URLSearchParams,
): Record<string, number> =>
  codes.reduce<Record<string, number>>((acc, code) => {
    const parsed = Number(searchParams.get(code));
    if (Number.isFinite(parsed)) {
      acc[code] = parsed;
    }
    return acc;
  }, {});

const hasCompleteSelection = (
  selected: Record<string, number>,
  requiredCodes: string[],
) => requiredCodes.every((code) => Number.isFinite(selected[code]));

const variantExists = (
  variantIndex: Record<string, Record<string, number>>,
  selected: Record<string, number>,
) =>
  Object.values(variantIndex).some((candidate) =>
    Object.entries(selected).every(([code, optionId]) => candidate[code] === optionId),
  );

const getRequiredCodesForOffer = (
  offer: CodOffer,
  fallback: string[],
): string[] =>
  Array.isArray(offer.required_attributes) && offer.required_attributes.length > 0
    ? offer.required_attributes
    : fallback;

const currency = (config?: CodCheckoutConfigResponse | null) =>
  config?.product_snapshot?.currency_code || "USD";

const defaultForm = {
  name: "",
  whatsapp: "",
  country_code: "",
  region_id: "",
  city_id: "",
  address1: "",
  address2: "",
  email: "",
};

export default function CodQuickCheckout({ productId }: CodQuickCheckoutProps) {
  const [config, setConfig] = useState<CodCheckoutConfigResponse | null>(null);
  const [isLoadingConfig, setIsLoadingConfig] = useState(true);
  const [isOpen, setIsOpen] = useState(false);
  const [step, setStep] = useState<Step>(1);
  const [selectedOfferId, setSelectedOfferId] = useState<number | null>(null);
  const [singleSelection, setSingleSelection] = useState<Record<string, number>>({});
  const [offerSharedSelection, setOfferSharedSelection] = useState<Record<string, number>>({});
  const [offerPerUnitSelections, setOfferPerUnitSelections] = useState<
    Array<Record<string, number>>
  >([]);
  const [form, setForm] = useState(defaultForm);
  const [countries, setCountries] = useState<Array<{ code: string; name: string }>>([]);
  const [regions, setRegions] = useState<Array<{ id: string; name: string }>>([]);
  const [cities, setCities] = useState<Array<{ id: string; name: string }>>([]);
  const [selectedShippingCode, setSelectedShippingCode] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [errorMessage, setErrorMessage] = useState("");

  const router = useRouter();
  const searchParams = useSearchParams();
  const { showToast } = useCustomToast();
  const dialogRef = useRef<HTMLDivElement | null>(null);

  const productSnapshot = config?.product_snapshot || null;
  const productAttributeCodes = useMemo(
    () => (productSnapshot?.attributes || []).map((attr) => attr.code),
    [productSnapshot],
  );

  const offers = useMemo(
    () => (Array.isArray(config?.offers) ? config?.offers.filter((offer) => offer.status) : []),
    [config],
  );

  const selectedOffer = useMemo(
    () => offers.find((offer) => offer.id === selectedOfferId) || null,
    [offers, selectedOfferId],
  );

  const isOfferMode = Boolean(selectedOffer);

  const availableShippingMethods = useMemo(() => {
    if (!Array.isArray(config?.shipping_methods)) return [];

    return config.shipping_methods.filter((method) => {
      if (!config.rules.allowed_shipping_methods?.length) return true;
      return config.rules.allowed_shipping_methods.includes(method.code);
    });
  }, [config]);

  const selectedShippingMethod = useMemo(
    () => availableShippingMethods.find((method) => method.code === selectedShippingCode) || null,
    [availableShippingMethods, selectedShippingCode],
  );

  const unitsCount = useMemo(() => {
    if (isOfferMode && selectedOffer) return selectedOffer.units_count;
    return 1;
  }, [isOfferMode, selectedOffer]);

  const subtotal = useMemo(() => {
    if (!config || !productSnapshot) return 0;
    if (selectedOffer) return parseNumber(selectedOffer.price);
    return parseNumber(productSnapshot.base_price);
  }, [config, productSnapshot, selectedOffer]);

  const discountTotal = useMemo(() => {
    if (!selectedOffer) return 0;
    if (selectedOffer.compare_at_price == null) return 0;
    return Math.max(0, parseNumber(selectedOffer.compare_at_price) - parseNumber(selectedOffer.price));
  }, [selectedOffer]);

  const feeTotal = useMemo(() => {
    if (!config) return 0;

    if (config.fee.type === "fixed") {
      return Math.max(0, parseNumber(config.fee.value));
    }

    if (config.fee.type === "percent") {
      return Math.max(0, (subtotal * parseNumber(config.fee.value)) / 100);
    }

    return 0;
  }, [config, subtotal]);

  const shippingTotal = useMemo(() => parseNumber(selectedShippingMethod?.price), [selectedShippingMethod]);

  const grandTotal = useMemo(
    () => subtotal + shippingTotal + feeTotal,
    [subtotal, shippingTotal, feeTotal],
  );

  const requiredCountryIsFixed = useMemo(() => {
    if (!config?.rules?.countries?.length) return false;
    return config.rules.countries.length === 1;
  }, [config]);

  useEffect(() => {
    let mounted = true;

    const run = async () => {
      setIsLoadingConfig(true);

      try {
        const response = await fetch(
          `/api/checkout/cod/config?product_id=${encodeURIComponent(String(productId))}`,
          {
            method: "GET",
            headers: {
              Accept: "application/json",
            },
            cache: "no-store",
          },
        );

        const payload = (await response.json()) as CodCheckoutConfigResponse & {
          error?: string;
        };

        if (!mounted) return;

        if (response.status === 403) {
          setConfig(payload);
          return;
        }

        if (!response.ok) {
          setConfig(null);
          return;
        }

        setConfig(payload);
      } catch {
        if (mounted) {
          setConfig(null);
        }
      } finally {
        if (mounted) {
          setIsLoadingConfig(false);
        }
      }
    };

    run();

    return () => {
      mounted = false;
    };
  }, [productId]);

  useEffect(() => {
    if (!config || !config.product_snapshot) {
      return;
    }

    const urlParams = new URLSearchParams(searchParams.toString());
    const prefilled = parseSelectionsFromSearch(productAttributeCodes, urlParams);

    setSingleSelection(prefilled);
    setOfferSharedSelection(prefilled);

    if (config.rules.countries.length === 1) {
      setForm((prev) => ({
        ...prev,
        country_code: config.rules.countries[0],
      }));
    }

    if (config.shipping_methods.length > 0) {
      setSelectedShippingCode(config.shipping_methods[0].code);
    }
  }, [config, productAttributeCodes, searchParams]);

  useEffect(() => {
    if (!selectedOffer || selectedOffer.selection_strategy !== "per_unit_variant") {
      setOfferPerUnitSelections([]);
      return;
    }

    setOfferPerUnitSelections((prev) => {
      if (prev.length === selectedOffer.units_count) {
        return prev;
      }

      return Array.from({ length: selectedOffer.units_count }, (_, index) => prev[index] || {});
    });
  }, [selectedOffer]);

  useEffect(() => {
    if (!isOpen) return;

    const dialog = dialogRef.current;
    if (!dialog) return;

    const focusableSelector =
      'a[href],button:not([disabled]),textarea,input,select,[tabindex]:not([tabindex="-1"])';

    const focusableElements = Array.from(
      dialog.querySelectorAll<HTMLElement>(focusableSelector),
    ).filter((element) => !element.hasAttribute("disabled"));

    const firstFocusable = focusableElements[0];
    const lastFocusable = focusableElements[focusableElements.length - 1];

    firstFocusable?.focus();

    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        event.preventDefault();
        closeModal();
        return;
      }

      if (event.key !== "Tab" || focusableElements.length === 0) {
        return;
      }

      if (event.shiftKey && document.activeElement === firstFocusable) {
        event.preventDefault();
        lastFocusable?.focus();
      } else if (!event.shiftKey && document.activeElement === lastFocusable) {
        event.preventDefault();
        firstFocusable?.focus();
      }
    };

    document.body.style.overflow = "hidden";
    document.addEventListener("keydown", onKeyDown);

    return () => {
      document.body.style.overflow = "";
      document.removeEventListener("keydown", onKeyDown);
    };
  }, [isOpen]);

  useEffect(() => {
    if (!isOpen || step < 2) return;

    if (countries.length > 0) return;

    const loadCountries = async () => {
      try {
        const response = await fetch("/api/locations/countries", {
          method: "GET",
          headers: { Accept: "application/json" },
          cache: "no-store",
        });

        const payload = (await response.json()) as {
          countries?: Array<{ code: string; name: string }>;
        };

        if (Array.isArray(payload.countries)) {
          const nextCountries = payload.countries;
          setCountries(nextCountries);

          setForm((prev) => {
            const currentCountry = prev.country_code || config?.rules.countries?.[0] || "";
            if (currentCountry) {
              return prev;
            }

            const firstCountry = nextCountries[0]?.code || "";
            return {
              ...prev,
              country_code: firstCountry,
            };
          });
        }
      } catch {
        setCountries([]);
      }
    };

    loadCountries();
  }, [isOpen, step, countries.length, config?.rules.countries]);

  useEffect(() => {
    if (!isOpen || step < 2) return;

    const countryCode = form.country_code;
    if (!countryCode) {
      setRegions([]);
      setCities([]);
      return;
    }

    const loadRegions = async () => {
      try {
        const response = await fetch(
          `/api/locations/${encodeURIComponent(countryCode)}/regions`,
          {
            method: "GET",
            headers: { Accept: "application/json" },
            cache: "no-store",
          },
        );

        const payload = (await response.json()) as {
          regions?: Array<{ id: string; name: string }>;
        };

        const nextRegions = Array.isArray(payload.regions) ? payload.regions : [];
        setRegions(nextRegions);

        setForm((prev) => {
          const hasCurrent = nextRegions.some((region) => region.id === prev.region_id);
          if (hasCurrent) return prev;

          return {
            ...prev,
            region_id: nextRegions[0]?.id || "",
            city_id: "",
          };
        });
      } catch {
        setRegions([]);
      }
    };

    loadRegions();
  }, [form.country_code, isOpen, step]);

  useEffect(() => {
    if (!isOpen || step < 2) return;

    if (!form.country_code || !form.region_id) {
      setCities([]);
      return;
    }

    const loadCities = async () => {
      try {
        const response = await fetch(
          `/api/locations/${encodeURIComponent(form.country_code)}/cities?region_id=${encodeURIComponent(form.region_id)}`,
          {
            method: "GET",
            headers: { Accept: "application/json" },
            cache: "no-store",
          },
        );

        const payload = (await response.json()) as {
          cities?: Array<{ id: string; name: string }>;
        };

        const nextCities = Array.isArray(payload.cities) ? payload.cities : [];
        setCities(nextCities);

        setForm((prev) => {
          const hasCurrent = nextCities.some((city) => city.id === prev.city_id);
          if (hasCurrent) return prev;

          return {
            ...prev,
            city_id: nextCities[0]?.id || "",
          };
        });
      } catch {
        setCities([]);
      }
    };

    loadCities();
  }, [form.country_code, form.region_id, isOpen, step]);

  const closeModal = () => {
    setIsOpen(false);
    setStep(1);
    setErrorMessage("");
  };

  const validateStep1 = (): boolean => {
    if (!config || !productSnapshot) return false;

    const hasVariants = productSnapshot.has_variants;

    if (!isOfferMode) {
      if (!hasVariants) return true;

      if (!hasCompleteSelection(singleSelection, productAttributeCodes)) {
        setErrorMessage("Debes seleccionar todas las variantes del producto.");
        return false;
      }

      if (!variantExists(productSnapshot.variant_index, singleSelection)) {
        setErrorMessage("La combinación de variantes no es válida.");
        return false;
      }

      return true;
    }

    if (!selectedOffer) {
      setErrorMessage("Selecciona una oferta válida.");
      return false;
    }

    const requiredCodes = getRequiredCodesForOffer(selectedOffer, productAttributeCodes);

    if (selectedOffer.selection_strategy === "none") {
      return true;
    }

    if (selectedOffer.selection_strategy === "single_variant_for_all") {
      if (!hasCompleteSelection(offerSharedSelection, requiredCodes)) {
        setErrorMessage("Debes seleccionar las variantes requeridas para la oferta.");
        return false;
      }

      if (!variantExists(productSnapshot.variant_index, offerSharedSelection)) {
        setErrorMessage("La combinación de variantes para la oferta no es válida.");
        return false;
      }

      return true;
    }

    if (offerPerUnitSelections.length !== selectedOffer.units_count) {
      setErrorMessage("Debes seleccionar variantes para todas las unidades del combo.");
      return false;
    }

    for (let index = 0; index < offerPerUnitSelections.length; index += 1) {
      const selection = offerPerUnitSelections[index];

      if (!hasCompleteSelection(selection, requiredCodes)) {
        setErrorMessage(`Debes completar las variantes de la unidad ${index + 1}.`);
        return false;
      }

      if (!variantExists(productSnapshot.variant_index, selection)) {
        setErrorMessage(`La combinación de la unidad ${index + 1} no es válida.`);
        return false;
      }
    }

    return true;
  };

  const validateStep2 = (): boolean => {
    if (!form.name.trim()) {
      setErrorMessage("El nombre y apellido son obligatorios.");
      return false;
    }

    if (config?.fields.require_whatsapp && !form.whatsapp.trim()) {
      setErrorMessage("El WhatsApp es obligatorio para esta tienda.");
      return false;
    }

    if (!form.country_code.trim()) {
      setErrorMessage("Debes seleccionar un país.");
      return false;
    }

    if (!form.region_id.trim()) {
      setErrorMessage("Debes seleccionar un estado/departamento.");
      return false;
    }

    if (!form.city_id.trim()) {
      setErrorMessage("Debes seleccionar una ciudad.");
      return false;
    }

    if (!form.address1.trim()) {
      setErrorMessage("La dirección es obligatoria.");
      return false;
    }

    if (!form.address2.trim()) {
      setErrorMessage("Los datos adicionales son obligatorios.");
      return false;
    }

    if (config?.fields.require_email && !form.email.trim()) {
      setErrorMessage("El email es obligatorio para esta tienda.");
      return false;
    }

    return true;
  };

  const buildOrderSelections = (): CodOrderRequestBody["selections"] => {
    if (!isOfferMode) {
      if (!productSnapshot?.has_variants) return undefined;
      return {
        attributes: singleSelection,
      };
    }

    if (!selectedOffer) return undefined;

    if (selectedOffer.selection_strategy === "none") {
      return undefined;
    }

    if (selectedOffer.selection_strategy === "single_variant_for_all") {
      return {
        attributes: offerSharedSelection,
      };
    }

    return offerPerUnitSelections.map((attributes) => ({
      attributes,
    }));
  };

  const submitOrder = async () => {
    if (!config || !productSnapshot) return;

    setIsSubmitting(true);
    setErrorMessage("");

    try {
      const payload: CodOrderRequestBody = {
        mode: isOfferMode ? "offer" : "single",
        product_id: productSnapshot.id,
        ...(isOfferMode && selectedOffer ? { offer_id: selectedOffer.id } : {}),
        units_count: unitsCount,
        selections: buildOrderSelections(),
        shipping_address: {
          name: form.name.trim(),
          whatsapp: form.whatsapp.trim(),
          country_code: form.country_code,
          region_id: form.region_id,
          city_id: form.city_id,
          address1: form.address1.trim(),
          address2: form.address2.trim(),
          email: form.email.trim(),
        },
        shipping_method_code: selectedShippingCode,
      };

      const response = await fetch("/api/checkout/cod/order", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Accept: "application/json",
        },
        body: JSON.stringify(payload),
      });

      const data = (await response.json()) as {
        order_id?: string;
        order_number?: string;
        redirect_url?: string;
        error?: string;
      };

      if (!response.ok || !data.order_id) {
        throw new Error(data.error || "No se pudo confirmar tu pedido COD.");
      }

      setCookie(ORDER_ID, data.order_number || data.order_id);

      showToast("Tu pedido contraentrega fue creado correctamente.", "success");
      closeModal();

      router.push(data.redirect_url || "/success");
    } catch (error) {
      const message =
        error instanceof Error
          ? error.message
          : "No se pudo confirmar tu pedido COD.";

      setErrorMessage(message);
      showToast(message, "warning");
    } finally {
      setIsSubmitting(false);
    }
  };

  if (isLoadingConfig || !config || !productSnapshot) {
    return null;
  }

  if (
    !config.allowed_by_plan ||
    !config.cod_active ||
    !config.available ||
    !config.modal.modal_enabled
  ) {
    return null;
  }

  const nextLabel = step === 3 ? "Confirmar pedido" : "Continuar";

  const goNext = () => {
    setErrorMessage("");

    if (step === 1) {
      if (!validateStep1()) return;
      setStep(2);
      return;
    }

    if (step === 2) {
      if (!validateStep2()) return;
      if (!selectedShippingCode && availableShippingMethods[0]) {
        setSelectedShippingCode(availableShippingMethods[0].code);
      }
      setStep(3);
      return;
    }

    if (!selectedShippingCode) {
      setErrorMessage("Debes seleccionar un método de envío.");
      return;
    }

    submitOrder();
  };

  return (
    <>
      <button
        type="button"
        onClick={() => {
          setIsOpen(true);
          setStep(1);
          setErrorMessage("");
        }}
        className="inline-flex h-fit w-full items-center justify-center rounded-full border border-neutral-900 bg-white px-6 py-4 text-sm font-semibold text-neutral-900 transition hover:bg-neutral-900 hover:text-white sm:w-auto sm:min-w-[14rem]"
      >
        {config.modal.modal_cta_text}
      </button>

      {isOpen && (
        <div className="cod-modal-root fixed inset-0 z-[120] flex items-end justify-center bg-black/45 p-0 md:items-center md:p-4">
          <div
            role="dialog"
            aria-modal="true"
            aria-label="Compra rápida contraentrega"
            ref={dialogRef}
            className="flex h-[92vh] w-full max-w-4xl flex-col overflow-hidden rounded-t-2xl bg-white text-black shadow-2xl md:h-auto md:max-h-[90vh] md:rounded-2xl"
          >
            <div className="flex items-center justify-between border-b border-neutral-200 px-4 py-3 md:px-6">
              <div>
                <p className="text-sm font-medium text-neutral-500">Paso {step} de 3</p>
                <h2 className="text-base font-semibold md:text-lg">Pago contraentrega</h2>
              </div>
              <button
                type="button"
                onClick={closeModal}
                className="rounded-md px-2 py-1 text-sm font-medium text-neutral-500 transition hover:bg-neutral-100 hover:text-neutral-900"
              >
                Cerrar
              </button>
            </div>

            <div className="flex-1 overflow-y-auto px-4 py-4 md:px-6 md:py-5">
              {step === 1 && (
                <section className="space-y-5">
                  <div className="grid gap-4 rounded-xl border border-neutral-200 p-4 md:grid-cols-[108px_1fr] md:items-center">
                    <div className="h-[96px] w-[96px] overflow-hidden rounded-lg border border-neutral-100">
                      <NextImage
                        src={productSnapshot.image || NOT_IMAGE}
                        alt={productSnapshot.title}
                        width={96}
                        height={96}
                      />
                    </div>
                    <div>
                      <p className="text-base font-semibold">{productSnapshot.title}</p>
                      <p className="mt-1 text-sm text-neutral-500">{config.modal.modal_helper_text}</p>
                      <div className="mt-2">
                        <Price
                          amount={String(productSnapshot.base_price)}
                          currencyCode={currency(config)}
                          className="text-base font-semibold"
                        />
                      </div>
                      <p className="mt-1 text-xs text-neutral-500">
                        Cantidad: {unitsCount}
                      </p>
                    </div>
                  </div>

                  {offers.length > 0 && (
                    <div className="space-y-2">
                      <p className="text-sm font-medium">Selecciona una modalidad</p>

                      <label className="block cursor-pointer rounded-xl border border-neutral-200 p-3 transition hover:border-blue-400">
                        <input
                          type="radio"
                          name="cod-offer"
                          className="mr-2"
                          checked={!isOfferMode}
                          onChange={() => setSelectedOfferId(null)}
                        />
                        <span className="text-sm font-medium">Producto individual (1 unidad)</span>
                      </label>

                      {offers.map((offer) => (
                        <label
                          key={offer.id}
                          className={clsx(
                            "block cursor-pointer rounded-xl border p-3 transition",
                            selectedOfferId === offer.id
                              ? "border-blue-500 bg-blue-50"
                              : "border-neutral-200 hover:border-blue-400",
                          )}
                        >
                          <input
                            type="radio"
                            name="cod-offer"
                            className="mr-2"
                            checked={selectedOfferId === offer.id}
                            onChange={() => setSelectedOfferId(offer.id)}
                          />
                          <span className="text-sm font-semibold">{offer.title}</span>
                          {offer.badge_text ? (
                            <span className="ml-2 rounded-full bg-neutral-900 px-2 py-0.5 text-[11px] font-semibold uppercase text-white">
                              {offer.badge_text}
                            </span>
                          ) : null}
                          {offer.subtitle ? (
                            <p className="mt-1 text-xs text-neutral-500">{offer.subtitle}</p>
                          ) : null}
                          <div className="mt-2 flex items-center gap-3">
                            <Price
                              amount={String(offer.price)}
                              currencyCode={currency(config)}
                              className="text-sm font-semibold"
                            />
                            {offer.compare_at_price ? (
                              <Price
                                amount={String(offer.compare_at_price)}
                                currencyCode={currency(config)}
                                className="text-xs text-neutral-500 line-through"
                              />
                            ) : null}
                            <span className="text-xs text-neutral-600">{offer.units_count} unidades</span>
                          </div>
                        </label>
                      ))}
                    </div>
                  )}

                  {productSnapshot.has_variants && (
                    <div className="space-y-3 rounded-xl border border-neutral-200 p-4">
                      <p className="text-sm font-medium">Variantes</p>

                      {!isOfferMode &&
                        productSnapshot.attributes.map((attribute) => (
                          <div key={`single-${attribute.code}`}>
                            <label className="mb-1 block text-xs font-medium text-neutral-600">
                              {attribute.label}
                            </label>
                            <select
                              value={singleSelection[attribute.code] || ""}
                              onChange={(event) =>
                                setSingleSelection((prev) => ({
                                  ...prev,
                                  [attribute.code]: Number(event.target.value),
                                }))
                              }
                              className="w-full rounded-lg border border-neutral-300 px-3 py-2 text-sm"
                            >
                              <option value="">Selecciona</option>
                              {attribute.options.map((option) => (
                                <option key={`${attribute.code}-${option.id}`} value={option.id}>
                                  {option.label}
                                </option>
                              ))}
                            </select>
                          </div>
                        ))}

                      {isOfferMode &&
                        selectedOffer &&
                        selectedOffer.selection_strategy === "single_variant_for_all" &&
                        getRequiredCodesForOffer(selectedOffer, productAttributeCodes).map((code) => {
                          const attribute = productSnapshot.attributes.find((item) => item.code === code);
                          if (!attribute) return null;

                          return (
                            <div key={`offer-shared-${attribute.code}`}>
                              <label className="mb-1 block text-xs font-medium text-neutral-600">
                                {attribute.label}
                              </label>
                              <select
                                value={offerSharedSelection[attribute.code] || ""}
                                onChange={(event) =>
                                  setOfferSharedSelection((prev) => ({
                                    ...prev,
                                    [attribute.code]: Number(event.target.value),
                                  }))
                                }
                                className="w-full rounded-lg border border-neutral-300 px-3 py-2 text-sm"
                              >
                                <option value="">Selecciona</option>
                                {attribute.options.map((option) => (
                                  <option key={`${attribute.code}-${option.id}`} value={option.id}>
                                    {option.label}
                                  </option>
                                ))}
                              </select>
                            </div>
                          );
                        })}

                      {isOfferMode &&
                        selectedOffer &&
                        selectedOffer.selection_strategy === "per_unit_variant" &&
                        offerPerUnitSelections.map((selection, unitIndex) => (
                          <div key={`per-unit-${unitIndex}`} className="space-y-2 rounded-lg border border-neutral-200 p-3">
                            <p className="text-xs font-semibold text-neutral-700">Unidad {unitIndex + 1}</p>
                            {getRequiredCodesForOffer(selectedOffer, productAttributeCodes).map((code) => {
                              const attribute = productSnapshot.attributes.find((item) => item.code === code);
                              if (!attribute) return null;

                              return (
                                <div key={`per-unit-${unitIndex}-${code}`}>
                                  <label className="mb-1 block text-xs font-medium text-neutral-600">
                                    {attribute.label}
                                  </label>
                                  <select
                                    value={selection[attribute.code] || ""}
                                    onChange={(event) =>
                                      setOfferPerUnitSelections((prev) =>
                                        prev.map((entry, currentIndex) =>
                                          currentIndex === unitIndex
                                            ? {
                                                ...entry,
                                                [attribute.code]: Number(event.target.value),
                                              }
                                            : entry,
                                        ),
                                      )
                                    }
                                    className="w-full rounded-lg border border-neutral-300 px-3 py-2 text-sm"
                                  >
                                    <option value="">Selecciona</option>
                                    {attribute.options.map((option) => (
                                      <option key={`${attribute.code}-${option.id}`} value={option.id}>
                                        {option.label}
                                      </option>
                                    ))}
                                  </select>
                                </div>
                              );
                            })}
                          </div>
                        ))}
                    </div>
                  )}
                </section>
              )}

              {step === 2 && (
                <section className="space-y-4">
                  <h3 className="text-sm font-semibold">Datos de envío</h3>

                  <div className="grid gap-3 md:grid-cols-2">
                    <label className="text-xs font-medium text-neutral-700">
                      Nombre y apellido *
                      <input
                        type="text"
                        value={form.name}
                        onChange={(event) =>
                          setForm((prev) => ({ ...prev, name: event.target.value }))
                        }
                        className="mt-1 w-full rounded-lg border border-neutral-300 px-3 py-2 text-sm"
                      />
                    </label>

                    <label className="text-xs font-medium text-neutral-700">
                      WhatsApp {config.fields.require_whatsapp ? "*" : ""}
                      <input
                        type="tel"
                        value={form.whatsapp}
                        onChange={(event) =>
                          setForm((prev) => ({ ...prev, whatsapp: event.target.value }))
                        }
                        className="mt-1 w-full rounded-lg border border-neutral-300 px-3 py-2 text-sm"
                      />
                    </label>
                  </div>

                  {!requiredCountryIsFixed && (
                    <label className="block text-xs font-medium text-neutral-700">
                      País *
                      <select
                        value={form.country_code}
                        onChange={(event) =>
                          setForm((prev) => ({
                            ...prev,
                            country_code: event.target.value,
                            region_id: "",
                            city_id: "",
                          }))
                        }
                        className="mt-1 w-full rounded-lg border border-neutral-300 px-3 py-2 text-sm"
                      >
                        <option value="">Selecciona</option>
                        {(countries.length > 0 ? countries : []).map((country) => (
                          <option key={country.code} value={country.code}>
                            {country.name}
                          </option>
                        ))}
                      </select>
                    </label>
                  )}

                  {requiredCountryIsFixed && (
                    <p className="text-xs text-neutral-500">
                      País: <span className="font-medium text-neutral-700">{form.country_code}</span>
                    </p>
                  )}

                  <div className="grid gap-3 md:grid-cols-2">
                    <label className="text-xs font-medium text-neutral-700">
                      Departamento / Estado *
                      <select
                        value={form.region_id}
                        onChange={(event) =>
                          setForm((prev) => ({
                            ...prev,
                            region_id: event.target.value,
                            city_id: "",
                          }))
                        }
                        className="mt-1 w-full rounded-lg border border-neutral-300 px-3 py-2 text-sm"
                      >
                        <option value="">Selecciona</option>
                        {regions.map((region) => (
                          <option key={region.id} value={region.id}>
                            {region.name}
                          </option>
                        ))}
                      </select>
                    </label>

                    <label className="text-xs font-medium text-neutral-700">
                      Ciudad *
                      <select
                        value={form.city_id}
                        onChange={(event) =>
                          setForm((prev) => ({ ...prev, city_id: event.target.value }))
                        }
                        className="mt-1 w-full rounded-lg border border-neutral-300 px-3 py-2 text-sm"
                      >
                        <option value="">Selecciona</option>
                        {cities.map((city) => (
                          <option key={city.id} value={city.id}>
                            {city.name}
                          </option>
                        ))}
                      </select>
                    </label>
                  </div>

                  <label className="block text-xs font-medium text-neutral-700">
                    Dirección *
                    <input
                      type="text"
                      value={form.address1}
                      onChange={(event) =>
                        setForm((prev) => ({ ...prev, address1: event.target.value }))
                      }
                      className="mt-1 w-full rounded-lg border border-neutral-300 px-3 py-2 text-sm"
                    />
                  </label>

                  <label className="block text-xs font-medium text-neutral-700">
                    Datos adicionales *
                    <input
                      type="text"
                      value={form.address2}
                      onChange={(event) =>
                        setForm((prev) => ({ ...prev, address2: event.target.value }))
                      }
                      className="mt-1 w-full rounded-lg border border-neutral-300 px-3 py-2 text-sm"
                    />
                  </label>

                  <label className="block text-xs font-medium text-neutral-700">
                    Email {config.fields.require_email ? "*" : ""}
                    <input
                      type="email"
                      value={form.email}
                      onChange={(event) =>
                        setForm((prev) => ({ ...prev, email: event.target.value }))
                      }
                      className="mt-1 w-full rounded-lg border border-neutral-300 px-3 py-2 text-sm"
                    />
                  </label>
                </section>
              )}

              {step === 3 && (
                <section className="space-y-5">
                  <div>
                    <h3 className="text-sm font-semibold">Método de envío</h3>
                    <div className="mt-2 space-y-2">
                      {availableShippingMethods.map((method) => (
                        <label
                          key={method.code}
                          className={clsx(
                            "block cursor-pointer rounded-lg border p-3 transition",
                            selectedShippingCode === method.code
                              ? "border-blue-500 bg-blue-50"
                              : "border-neutral-200 hover:border-blue-400",
                          )}
                        >
                          <input
                            type="radio"
                            name="cod-shipping"
                            className="mr-2"
                            checked={selectedShippingCode === method.code}
                            onChange={() => setSelectedShippingCode(method.code)}
                          />
                          <span className="text-sm font-medium">{method.label}</span>
                          {method.description ? (
                            <p className="mt-1 text-xs text-neutral-500">{method.description}</p>
                          ) : null}
                          <div className="mt-1 text-xs font-semibold text-neutral-700">
                            <Price
                              amount={String(method.price)}
                              currencyCode={currency(config)}
                              className="text-xs font-semibold"
                            />
                          </div>
                        </label>
                      ))}
                    </div>
                  </div>

                  <div className="rounded-xl border border-neutral-200 p-4">
                    <h4 className="text-sm font-semibold">Resumen</h4>
                    <div className="mt-3 space-y-2 text-sm">
                      <div className="flex items-center justify-between">
                        <span className="text-neutral-600">Subtotal</span>
                        <Price amount={String(subtotal)} currencyCode={currency(config)} className="font-medium" />
                      </div>

                      <div className="flex items-center justify-between">
                        <span className="text-neutral-600">Envío</span>
                        <Price amount={String(shippingTotal)} currencyCode={currency(config)} className="font-medium" />
                      </div>

                      <div className="flex items-center justify-between">
                        <span className="text-neutral-600">Descuentos</span>
                        <Price amount={String(discountTotal)} currencyCode={currency(config)} className="font-medium" />
                      </div>

                      <div className="flex items-center justify-between">
                        <span className="text-neutral-600">Fee COD</span>
                        <Price amount={String(feeTotal)} currencyCode={currency(config)} className="font-medium" />
                      </div>

                      <div className="mt-2 border-t border-neutral-200 pt-2">
                        <div className="flex items-center justify-between text-base font-semibold">
                          <span>Total</span>
                          <Price amount={String(grandTotal)} currencyCode={currency(config)} className="text-base font-semibold" />
                        </div>
                      </div>
                    </div>

                    <p className="mt-3 text-xs text-neutral-500">
                      Método de pago: <strong>Contraentrega</strong>. Estado inicial:
                      <strong> Pago pendiente</strong>.
                    </p>
                  </div>
                </section>
              )}
            </div>

            <div className="border-t border-neutral-200 px-4 py-3 md:px-6">
              {errorMessage ? <p className="mb-2 text-sm text-red-600">{errorMessage}</p> : null}

              <div className="flex flex-col gap-2 sm:flex-row sm:justify-between">
                <button
                  type="button"
                  onClick={() => {
                    if (step === 1) {
                      closeModal();
                      return;
                    }
                    setErrorMessage("");
                    setStep((prev) => (prev === 1 ? 1 : ((prev - 1) as Step)));
                  }}
                  className="rounded-lg border border-neutral-300 px-4 py-2 text-sm font-medium text-neutral-700 transition hover:bg-neutral-100"
                >
                  {step === 1 ? "Cancelar" : "Atrás"}
                </button>

                <button
                  type="button"
                  onClick={goNext}
                  disabled={isSubmitting}
                  className={clsx(
                    "rounded-lg bg-blue-600 px-5 py-2 text-sm font-semibold text-white transition hover:bg-blue-700",
                    isSubmitting && "cursor-wait opacity-60",
                  )}
                >
                  {isSubmitting ? "Procesando..." : nextLabel}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

"use client";

import { CodPortalOrder } from "@/types/cod";
import { Price } from "@/components/theme/ui/Price";
import { useCustomToast } from "@/utils/hooks/useToast";
import { useEffect, useState } from "react";

export default function CodOrdersPanel() {
  const { showToast } = useCustomToast();
  const [loading, setLoading] = useState(true);
  const [orders, setOrders] = useState<CodPortalOrder[]>([]);
  const [markingOrderId, setMarkingOrderId] = useState<string | null>(null);

  const load = async () => {
    setLoading(true);
    try {
      const response = await fetch("/api/portal/orders", {
        method: "GET",
        headers: { Accept: "application/json" },
        cache: "no-store",
      });

      const payload = (await response.json()) as {
        orders?: CodPortalOrder[];
        error?: string;
      };

      if (!response.ok) {
        throw new Error(payload.error || "No se pudieron cargar órdenes COD.");
      }

      setOrders(Array.isArray(payload.orders) ? payload.orders : []);
    } catch (error) {
      showToast(
        error instanceof Error ? error.message : "No se pudieron cargar órdenes COD.",
        "warning",
      );
      setOrders([]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
  }, []);

  const markPaid = async (orderId: string) => {
    setMarkingOrderId(orderId);

    try {
      const response = await fetch(`/api/portal/orders/${orderId}/cod/mark-paid`, {
        method: "POST",
        headers: { Accept: "application/json" },
      });

      const payload = (await response.json()) as {
        error?: string;
      };

      if (!response.ok) {
        throw new Error(payload.error || "No se pudo marcar la orden como pagada.");
      }

      await load();
      showToast("Orden marcada como pagada.", "success");
    } catch (error) {
      showToast(
        error instanceof Error ? error.message : "No se pudo marcar la orden como pagada.",
        "warning",
      );
    } finally {
      setMarkingOrderId(null);
    }
  };

  if (loading) {
    return <p className="text-sm text-neutral-500">Cargando órdenes COD...</p>;
  }

  if (orders.length === 0) {
    return (
      <div className="rounded-xl border border-neutral-200 bg-white p-4 text-sm text-neutral-500">
        No hay órdenes COD registradas.
      </div>
    );
  }

  return (
    <div className="space-y-3">
      {orders.map((order) => (
        <article key={order.order_id} className="rounded-xl border border-neutral-200 bg-white p-4">
          <div className="flex flex-wrap items-center justify-between gap-2">
            <div>
              <p className="text-sm font-semibold">Orden #{order.order_number}</p>
              <p className="text-xs text-neutral-500">{new Date(order.created_at).toLocaleString()}</p>
            </div>

            <div className="flex items-center gap-2">
              <span className="rounded-full bg-blue-100 px-2 py-0.5 text-[10px] font-semibold uppercase text-blue-700">
                Contraentrega
              </span>
              <span
                className={`rounded-full px-2 py-0.5 text-[10px] font-semibold uppercase ${
                  order.payment_status === "paid"
                    ? "bg-emerald-100 text-emerald-700"
                    : "bg-amber-100 text-amber-700"
                }`}
              >
                {order.payment_status === "paid" ? "Pago realizado" : "Pago pendiente"}
              </span>
            </div>
          </div>

          <div className="mt-3 grid gap-3 md:grid-cols-2">
            <div className="rounded-lg border border-neutral-200 p-3">
              <p className="text-xs font-semibold uppercase tracking-wide text-neutral-500">Cliente</p>
              <p className="mt-1 text-sm font-medium">{order.customer.name}</p>
              <p className="text-xs text-neutral-600">WhatsApp: {order.customer.whatsapp || "-"}</p>
              <p className="text-xs text-neutral-600">Email: {order.customer.email || "-"}</p>
              <p className="mt-1 text-xs text-neutral-600">
                {order.customer.country_code} / {order.customer.region_id} / {order.customer.city_id}
              </p>
              <p className="text-xs text-neutral-600">{order.customer.address1}</p>
              <p className="text-xs text-neutral-600">{order.customer.address2}</p>
            </div>

            <div className="rounded-lg border border-neutral-200 p-3">
              <p className="text-xs font-semibold uppercase tracking-wide text-neutral-500">Resumen</p>
              <p className="mt-1 text-sm font-medium">{order.product_title}</p>
              <div className="mt-2 space-y-1 text-xs">
                <div className="flex items-center justify-between">
                  <span className="text-neutral-500">Subtotal</span>
                  <Price amount={String(order.subtotal)} className="font-medium" currencyCode="USD" />
                </div>
                <div className="flex items-center justify-between">
                  <span className="text-neutral-500">Envío</span>
                  <Price amount={String(order.shipping_total)} className="font-medium" currencyCode="USD" />
                </div>
                <div className="flex items-center justify-between">
                  <span className="text-neutral-500">Fee COD</span>
                  <Price amount={String(order.cod_fee_total)} className="font-medium" currencyCode="USD" />
                </div>
                <div className="mt-1 flex items-center justify-between border-t border-neutral-200 pt-1 text-sm font-semibold">
                  <span>Total</span>
                  <Price amount={String(order.grand_total)} className="font-semibold" currencyCode="USD" />
                </div>
              </div>
            </div>
          </div>

          {order.payment_status === "pending" ? (
            <div className="mt-3 flex justify-end">
              <button
                type="button"
                onClick={() => markPaid(order.order_id)}
                disabled={markingOrderId === order.order_id}
                className="rounded-lg bg-emerald-600 px-3 py-1.5 text-xs font-semibold text-white transition hover:bg-emerald-700 disabled:cursor-wait disabled:opacity-60"
              >
                {markingOrderId === order.order_id ? "Procesando..." : "Marcar como pagado"}
              </button>
            </div>
          ) : null}
        </article>
      ))}
    </div>
  );
}

"use client";

import { CodTenantSettings } from "@/types/cod";
import { useCustomToast } from "@/utils/hooks/useToast";
import { useEffect, useMemo, useState } from "react";

const defaultSettings: CodTenantSettings = {
  plan_name: "emprendedor",
  active: false,
  title: "Pago contraentrega",
  description: "Paga cuando recibas tu pedido.",
  countries: ["CO", "MX", "AR"],
  min_total: null,
  max_total: null,
  allowed_shipping_methods: null,
  fee_type: "none",
  fee_value: null,
  require_email: false,
  require_whatsapp: true,
  modal_enabled: true,
  modal_cta_text: "COMPRA Y PAGA AL RECIBIR",
  modal_helper_text: "Completa tus datos de envío para confirmar tu pedido.",
};

export default function CodSettingsPanel() {
  const { showToast } = useCustomToast();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [allowedByPlan, setAllowedByPlan] = useState(true);
  const [settings, setSettings] = useState<CodTenantSettings>(defaultSettings);

  const countriesInput = useMemo(() => settings.countries.join(","), [settings.countries]);
  const shippingInput = useMemo(
    () => (settings.allowed_shipping_methods || []).join(","),
    [settings.allowed_shipping_methods],
  );

  const load = async () => {
    setLoading(true);
    try {
      const response = await fetch("/api/portal/cod/settings", {
        method: "GET",
        headers: { Accept: "application/json" },
        cache: "no-store",
      });

      const payload = (await response.json()) as {
        settings?: CodTenantSettings;
        allowed_by_plan?: boolean;
        error?: string;
      };

      if (payload.settings) {
        setSettings(payload.settings);
      }

      if (typeof payload.allowed_by_plan === "boolean") {
        setAllowedByPlan(payload.allowed_by_plan);
      } else {
        setAllowedByPlan(response.status !== 403);
      }

      if (!response.ok && payload.error) {
        showToast(payload.error, "warning");
      }
    } catch {
      showToast("No se pudo cargar configuración COD.", "warning");
      setAllowedByPlan(false);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
  }, []);

  const save = async () => {
    setSaving(true);

    try {
      const response = await fetch("/api/portal/cod/settings", {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          Accept: "application/json",
        },
        body: JSON.stringify(settings),
      });

      const payload = (await response.json()) as {
        settings?: CodTenantSettings;
        error?: string;
      };

      if (!response.ok) {
        throw new Error(payload.error || "No se pudo guardar configuración COD.");
      }

      if (payload.settings) {
        setSettings(payload.settings);
      }

      showToast("Configuración COD actualizada.", "success");
    } catch (error) {
      showToast(
        error instanceof Error ? error.message : "No se pudo guardar configuración COD.",
        "warning",
      );
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return <p className="text-sm text-neutral-500">Cargando configuración COD...</p>;
  }

  if (!allowedByPlan) {
    return (
      <div className="rounded-xl border border-amber-300 bg-amber-50 p-4 text-sm text-amber-900">
        El plan actual no tiene habilitada la feature <strong>cash_on_delivery</strong>.
      </div>
    );
  }

  return (
    <div className="grid gap-6 lg:grid-cols-[1.4fr_1fr]">
      <section className="rounded-xl border border-neutral-200 bg-white p-4">
        <h2 className="text-lg font-semibold">Settings COD</h2>

        <div className="mt-4 grid gap-3 md:grid-cols-2">
          <label className="text-xs font-medium text-neutral-700">
            Plan
            <select
              value={settings.plan_name}
              onChange={(event) =>
                setSettings((prev) => ({ ...prev, plan_name: event.target.value }))
              }
              className="mt-1 w-full rounded-lg border border-neutral-300 px-3 py-2 text-sm"
            >
              <option value="basic">Basic</option>
              <option value="emprendedor">Emprendedor</option>
              <option value="mipyme">MiPyme</option>
            </select>
          </label>

          <label className="text-xs font-medium text-neutral-700">
            Activo
            <select
              value={settings.active ? "1" : "0"}
              onChange={(event) =>
                setSettings((prev) => ({ ...prev, active: event.target.value === "1" }))
              }
              className="mt-1 w-full rounded-lg border border-neutral-300 px-3 py-2 text-sm"
            >
              <option value="0">No</option>
              <option value="1">Sí</option>
            </select>
          </label>
        </div>

        <div className="mt-3 grid gap-3">
          <label className="text-xs font-medium text-neutral-700">
            Título método
            <input
              value={settings.title}
              onChange={(event) =>
                setSettings((prev) => ({ ...prev, title: event.target.value }))
              }
              className="mt-1 w-full rounded-lg border border-neutral-300 px-3 py-2 text-sm"
            />
          </label>

          <label className="text-xs font-medium text-neutral-700">
            Descripción método
            <textarea
              value={settings.description}
              onChange={(event) =>
                setSettings((prev) => ({ ...prev, description: event.target.value }))
              }
              className="mt-1 min-h-[72px] w-full rounded-lg border border-neutral-300 px-3 py-2 text-sm"
            />
          </label>
        </div>

        <div className="mt-4 grid gap-3 md:grid-cols-2">
          <label className="text-xs font-medium text-neutral-700">
            Países habilitados (CSV)
            <input
              value={countriesInput}
              onChange={(event) =>
                setSettings((prev) => ({
                  ...prev,
                  countries: event.target.value
                    .split(",")
                    .map((item) => item.trim().toUpperCase())
                    .filter(Boolean),
                }))
              }
              className="mt-1 w-full rounded-lg border border-neutral-300 px-3 py-2 text-sm"
            />
          </label>

          <label className="text-xs font-medium text-neutral-700">
            Shipping permitido (CSV)
            <input
              value={shippingInput}
              onChange={(event) =>
                setSettings((prev) => ({
                  ...prev,
                  allowed_shipping_methods: event.target.value.trim()
                    ? event.target.value
                        .split(",")
                        .map((item) => item.trim())
                        .filter(Boolean)
                    : null,
                }))
              }
              className="mt-1 w-full rounded-lg border border-neutral-300 px-3 py-2 text-sm"
            />
          </label>

          <label className="text-xs font-medium text-neutral-700">
            Mínimo total
            <input
              type="number"
              value={settings.min_total ?? ""}
              onChange={(event) =>
                setSettings((prev) => ({
                  ...prev,
                  min_total: event.target.value === "" ? null : Number(event.target.value),
                }))
              }
              className="mt-1 w-full rounded-lg border border-neutral-300 px-3 py-2 text-sm"
            />
          </label>

          <label className="text-xs font-medium text-neutral-700">
            Máximo total
            <input
              type="number"
              value={settings.max_total ?? ""}
              onChange={(event) =>
                setSettings((prev) => ({
                  ...prev,
                  max_total: event.target.value === "" ? null : Number(event.target.value),
                }))
              }
              className="mt-1 w-full rounded-lg border border-neutral-300 px-3 py-2 text-sm"
            />
          </label>
        </div>

        <div className="mt-4 grid gap-3 md:grid-cols-3">
          <label className="text-xs font-medium text-neutral-700">
            Fee tipo
            <select
              value={settings.fee_type}
              onChange={(event) =>
                setSettings((prev) => ({
                  ...prev,
                  fee_type: event.target.value as CodTenantSettings["fee_type"],
                }))
              }
              className="mt-1 w-full rounded-lg border border-neutral-300 px-3 py-2 text-sm"
            >
              <option value="none">none</option>
              <option value="fixed">fixed</option>
              <option value="percent">percent</option>
            </select>
          </label>

          <label className="text-xs font-medium text-neutral-700">
            Fee valor
            <input
              type="number"
              value={settings.fee_value ?? ""}
              onChange={(event) =>
                setSettings((prev) => ({
                  ...prev,
                  fee_value: event.target.value === "" ? null : Number(event.target.value),
                }))
              }
              className="mt-1 w-full rounded-lg border border-neutral-300 px-3 py-2 text-sm"
            />
          </label>

          <label className="text-xs font-medium text-neutral-700">
            Modal habilitado
            <select
              value={settings.modal_enabled ? "1" : "0"}
              onChange={(event) =>
                setSettings((prev) => ({
                  ...prev,
                  modal_enabled: event.target.value === "1",
                }))
              }
              className="mt-1 w-full rounded-lg border border-neutral-300 px-3 py-2 text-sm"
            >
              <option value="1">Sí</option>
              <option value="0">No</option>
            </select>
          </label>
        </div>

        <div className="mt-4 grid gap-3 md:grid-cols-2">
          <label className="text-xs font-medium text-neutral-700">
            Require email
            <select
              value={settings.require_email ? "1" : "0"}
              onChange={(event) =>
                setSettings((prev) => ({ ...prev, require_email: event.target.value === "1" }))
              }
              className="mt-1 w-full rounded-lg border border-neutral-300 px-3 py-2 text-sm"
            >
              <option value="0">No</option>
              <option value="1">Sí</option>
            </select>
          </label>

          <label className="text-xs font-medium text-neutral-700">
            Require WhatsApp
            <select
              value={settings.require_whatsapp ? "1" : "0"}
              onChange={(event) =>
                setSettings((prev) => ({
                  ...prev,
                  require_whatsapp: event.target.value === "1",
                }))
              }
              className="mt-1 w-full rounded-lg border border-neutral-300 px-3 py-2 text-sm"
            >
              <option value="0">No</option>
              <option value="1">Sí</option>
            </select>
          </label>
        </div>

        <div className="mt-4 grid gap-3">
          <label className="text-xs font-medium text-neutral-700">
            Texto CTA modal
            <input
              value={settings.modal_cta_text}
              onChange={(event) =>
                setSettings((prev) => ({
                  ...prev,
                  modal_cta_text: event.target.value,
                }))
              }
              className="mt-1 w-full rounded-lg border border-neutral-300 px-3 py-2 text-sm"
            />
          </label>

          <label className="text-xs font-medium text-neutral-700">
            Texto helper modal
            <textarea
              value={settings.modal_helper_text}
              onChange={(event) =>
                setSettings((prev) => ({
                  ...prev,
                  modal_helper_text: event.target.value,
                }))
              }
              className="mt-1 min-h-[72px] w-full rounded-lg border border-neutral-300 px-3 py-2 text-sm"
            />
          </label>
        </div>

        <div className="mt-5 flex justify-end">
          <button
            type="button"
            onClick={save}
            disabled={saving}
            className="rounded-lg bg-blue-600 px-4 py-2 text-sm font-semibold text-white transition hover:bg-blue-700 disabled:cursor-wait disabled:opacity-60"
          >
            {saving ? "Guardando..." : "Guardar configuración"}
          </button>
        </div>
      </section>

      <aside className="rounded-xl border border-neutral-200 bg-white p-4">
        <h3 className="text-base font-semibold">Vista previa CTA</h3>
        <div className="mt-4 rounded-xl border border-neutral-200 p-4">
          <p className="text-sm font-semibold text-neutral-800">{settings.modal_cta_text}</p>
          <p className="mt-2 text-xs text-neutral-500">{settings.modal_helper_text}</p>
          <div className="mt-4 rounded-full border border-blue-500 px-3 py-2 text-center text-xs font-semibold text-blue-700">
            {settings.title}
          </div>
        </div>
      </aside>
    </div>
  );
}

import Link from "next/link";
import { Suspense } from "react";
import MobileMenu from "./MobileMenu";
import Search from "./Search";
import Cart from "@/components/cart";
import { SearchSkeleton } from "@/components/common/skeleton/SearchSkeleton";
import { IconSkeleton } from "@/components/common/skeleton/IconSkeleton";
import { GET_TREE_CATEGORIES, graphqlRequest } from "@/graphql";
import ThemeSwitcherWrapper from "@components/theme/theme-switch";
import LogoIcon from "@components/common/icons/LogoIcon";
import UserAccount from "@components/customer/credentials";
import { getStorefrontSeoPayload } from "@/utils/server/storefront-seo";

export default async function Navbar({
  allowsCheckout = true,
}: {
  allowsCheckout?: boolean;
}) {
  let filteredCategories: Array<{
    id: string;
    name: string;
    slug: string;
  }> = [];

  try {
    const data = await graphqlRequest<any>(
      GET_TREE_CATEGORIES,
      { getCategoryTree: true },
      { tags: ["categories"], life: "hours" }
    );

    const categories = Array.isArray(data?.homeCategories)
      ? data.homeCategories
      : [];

    filteredCategories = categories
      .filter((cat: any) => cat.id !== "1")
      .map((cat: any) => {
        return {
          id: cat.id,
          name: cat.name || "",
          slug: cat.slug || "",
        };
      })
      .filter((item: any) => item.name && item.slug);
  } catch (error) {
    console.error("Unable to resolve navbar categories:", error);
  }

  const branding = await getStorefrontSeoPayload();
  const logoSrc = branding?.image;
  const logoAlt = branding?.siteName || branding?.title || "JectStore";

  const menuData = [
    { id: "all", name: "Todo", slug: "" },
    ...filteredCategories.slice(0, 3),
  ];

  return (
    <>
      <header className="sticky top-0 z-10">
        <nav className="relative flex flex-col items-center justify-between gap-4 bg-neutral-50 p-4 dark:bg-neutral-900 md:flex-row lg:px-6 lg:py-4">
          <div className="flex w-full items-center justify-between gap-0 sm:gap-4">
            <div className="flex max-w-fit gap-2 xl:gap-6">
              <Suspense fallback={null}>
                <MobileMenu menu={menuData} allowsCheckout={allowsCheckout} />
              </Suspense>
              <Link
                className="flex h-9 w-full scale-95 items-center md:h-9 md:w-auto lg:h-10"
                href="/"
                aria-label="Ir al inicio"
              >
                <LogoIcon src={logoSrc} alt={logoAlt} />
              </Link>
              <ul className="hidden gap-4 text-sm md:items-center lg:flex xl:gap-6">
                {menuData.map(
                  (item: { id: string; name: string; slug: string }) => (
                    <li key={item?.id + item?.name}>
                      <Link
                        className="text-nowrap relative text-neutral-500 before:absolute before:bottom-0 before:left-0 before:h-px before:w-0 before:bg-current before:transition-all before:duration-300 before:content-[''] hover:text-black hover:before:w-full dark:text-neutral-400 dark:hover:text-neutral-300"
                        href={item.slug ? `/search/${item.slug}` : "/search"}
                        prefetch={true}
                        aria-label={`Ver productos de ${item.name}`}
                      >
                        {item.name}
                      </Link>
                    </li>
                  )
                )}
              </ul>
            </div>
            <div className="hidden flex-1 justify-center md:flex">
              <Suspense fallback={<SearchSkeleton />}>
                <Search search={false} />
              </Suspense>
            </div>
            <div className="flex max-w-fit gap-2 md:gap-4">
              <div className="flex">
                <ThemeSwitcherWrapper />
              </div>
              {allowsCheckout ? (
                <div className="hidden lg:block">
                  <Cart />
                </div>
              ) : null}
              <Suspense fallback={<IconSkeleton />}>
                <div className="hidden lg:block">
                  <UserAccount />
                </div>
              </Suspense>
            </div>
          </div>
        </nav>
      </header>
    </>
  );
}
